import{Z as e,e as o,f as r,a0 as i}from"./chunks/framework.DmpHOl9T.js";const h=JSON.parse('{"title":"Import and Export Between Environments","description":"","frontmatter":{},"headers":[],"relativePath":"guides/control-panel-admin/import-and-export-between-environments.md","filePath":"guides/control-panel-admin/import-and-export-between-environments.md","lastUpdated":1782532814000}'),n={name:"guides/control-panel-admin/import-and-export-between-environments.md"};function a(s,t,l,d,p,c){return o(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="import-and-export-between-environments" tabindex="-1">Import and Export Between Environments <a class="header-anchor" href="#import-and-export-between-environments" aria-label="Permalink to &quot;Import and Export Between Environments&quot;">​</a></h1><p>Form import and export moves <strong>form definitions</strong> between environments — not submission data. Use it when staging a new form for production, cloning a client&#39;s enquiry form to another project, or backing up structure before a major edit.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><a href="/forms/import-export">Import &amp; Export</a></li><li>Access to <strong>Formie → Settings → Import/Export</strong> on both environments</li></ul><h2 id="what-export-includes" tabindex="-1">What Export Includes <a class="header-anchor" href="#what-export-includes" aria-label="Permalink to &quot;What Export Includes&quot;">​</a></h2><p>Exporting a form produces a JSON file containing:</p><ul><li>Form details and settings</li><li>Pages and fields</li><li>Email notifications</li><li>Form template assignment</li><li>Email template assignment</li><li>PDF template assignment</li></ul><p>It is a structural snapshot — not a dump of submissions.</p><h2 id="what-export-does-not-include" tabindex="-1">What Export Does Not Include <a class="header-anchor" href="#what-export-does-not-include" aria-label="Permalink to &quot;What Export Does Not Include&quot;">​</a></h2><ul><li>Submissions</li><li>Integration OAuth tokens (reconnect integrations per environment)</li><li>Spam settings and captcha secrets (see <a href="/guides/configuration/project-config-environment-and-control-panel-settings">Project config, environment, and control panel settings</a>)</li><li>Synced field <strong>definitions</strong> (only placements in the form — ensure definitions exist on the target environment)</li></ul><h2 id="export-workflow" tabindex="-1">Export Workflow <a class="header-anchor" href="#export-workflow" aria-label="Permalink to &quot;Export Workflow&quot;">​</a></h2><ol><li>On the <strong>source</strong> environment, open <strong>Formie → Settings → Import/Export</strong></li><li>Select the form(s) to export</li><li>Download the JSON file</li><li>Commit to version control if your team tracks form structure in git (optional)</li></ol><p>For multiple forms, export one at a time or automate via console commands if your deployment pipeline supports it.</p><h2 id="import-workflow" tabindex="-1">Import Workflow <a class="header-anchor" href="#import-workflow" aria-label="Permalink to &quot;Import Workflow&quot;">​</a></h2><ol><li>On the <strong>target</strong> environment, open <strong>Formie → Settings → Import/Export</strong></li><li>Upload the JSON file</li><li>Review the preview — Formie validates the file format</li><li>Choose how to handle handle collisions:</li></ol><table tabindex="0"><thead><tr><th>Option</th><th>When to use</th></tr></thead><tbody><tr><td><strong>Create new form</strong></td><td>Production already has a different form with the same handle; import generates a unique handle (e.g. <code>contactForm1</code>)</td></tr><tr><td><strong>Update existing form</strong></td><td>Staging → production promotion where handles match and you intend a full overwrite</td></tr></tbody></table><blockquote><p>Updating an existing form is a <strong>full overwrite</strong> of structure — fields, notifications, and template assignments. Submissions remain, but field handles that changed can orphan old submission data. Take a backup or export first.</p></blockquote><ol start="5"><li>Complete the import and verify in the form builder</li></ol><p>Formie only supports its own export format. Arbitrary JSON will not import.</p><h2 id="environment-promotion-patterns" tabindex="-1">Environment Promotion Patterns <a class="header-anchor" href="#environment-promotion-patterns" aria-label="Permalink to &quot;Environment Promotion Patterns&quot;">​</a></h2><h3 id="staging-→-production-same-project" tabindex="-1">Staging → Production (Same Project) <a class="header-anchor" href="#staging-→-production-same-project" aria-label="Permalink to &quot;Staging → Production (Same Project)&quot;">​</a></h3><ol><li>Build and test the form on staging</li><li>Export JSON</li><li>Import on production with <strong>Update existing form</strong> if handles match</li><li>Re-test notifications, integrations, and captchas on production URLs</li><li>Run <code>project-config/sync</code> if the import touched project-scoped resources</li></ol><h3 id="client-template-→-new-project" tabindex="-1">Client Template → New Project <a class="header-anchor" href="#client-template-→-new-project" aria-label="Permalink to &quot;Client Template → New Project&quot;">​</a></h3><ol><li>Export the canonical template forms from your starter Craft install</li><li>Import on the client site as <strong>Create new form</strong></li><li>Rename handles to client conventions</li><li>Assign <a href="/forms/form-groups">form groups</a> and site policies for the client&#39;s multi-site setup</li></ol><h3 id="disaster-recovery-before-a-big-edit" tabindex="-1">Disaster Recovery Before a Big Edit <a class="header-anchor" href="#disaster-recovery-before-a-big-edit" aria-label="Permalink to &quot;Disaster Recovery Before a Big Edit&quot;">​</a></h3><p>Export the current form JSON before deleting fields or restructuring. Re-import if the edit goes wrong.</p><h2 id="combine-with-project-config" tabindex="-1">Combine with Project Config <a class="header-anchor" href="#combine-with-project-config" aria-label="Permalink to &quot;Combine with Project Config&quot;">​</a></h2><p>Some Formie resources travel via project config instead of import/export:</p><table tabindex="0"><thead><tr><th>Resource</th><th>Mechanism</th></tr></thead><tbody><tr><td>Form groups</td><td><code>formie.formGroups</code> in project config</td></tr><tr><td>Project stencils</td><td><code>formie.stencils</code> in project config</td></tr><tr><td>Submission statuses</td><td><code>formie.statuses</code></td></tr><tr><td>Reports</td><td><code>formie.reports</code></td></tr></tbody></table><p>Use import/export for <strong>individual form snapshots</strong>. Use project config for <strong>team-wide defaults and stencils</strong> that should version with code.</p><p>See <a href="/guides/control-panel-admin/stencils-for-repeatable-form-types">Stencils for repeatable form types</a>.</p><h2 id="post-import-checklist" tabindex="-1">Post-Import Checklist <a class="header-anchor" href="#post-import-checklist" aria-label="Permalink to &quot;Post-Import Checklist&quot;">​</a></h2><ul><li>Field handles unchanged (or migration plan for submission data)</li><li>Email notifications send from correct domain on target environment</li><li>Integrations reconnected with production credentials</li><li>Captcha keys set under <strong>Settings → Spam Protection</strong></li><li>Form enabled on expected sites (form group site policy)</li><li>Front-end template or headless app points at correct form handle</li><li>Test submit on production</li></ul>',33)])])}const u=e(n,[["render",a]]);export{h as __pageData,u as default};
